import sys, random, string
sys.path.insert(0, "/private/tmp/tmpekqlp4zb/pete/projects/minisql")
import minisql
D="/private/tmp/tmpekqlp4zb/tmp/minisql_probe"
random.seed(42)
cols=["id","x","s","k","v","a","b"]
tables=["t","empty","mixed","numeric","dups","one","ordalias","u","w"]
lits=["1","2","0","-1","1.5",".5","'a'","'%a%'","NULL","TRUE","FALSE"]
funcs=["LOWER","UPPER","LENGTH","ABS","ROUND","COALESCE","COUNT","SUM","AVG","MIN","MAX"]

def expr(d=0):
    k=random.random()
    if d>2 or k<0.35: return random.choice(cols+lits)
    if k<0.5: return "%s(%s)"%(random.choice(funcs), expr(d+1))
    if k<0.6: return "(%s)"%expr(d+1)
    if k<0.7: return "NOT %s"%expr(d+1)
    if k<0.8: return "%s %s %s"%(expr(d+1), random.choice(["+","-","*","/","||","=","!=","<","<=",">",">="]), expr(d+1))
    if k<0.9: return "%s %s (%s)"%(expr(d+1), random.choice(["IN","NOT IN"]), expr(d+1))
    return "%s BETWEEN %s AND %s"%(expr(d+1),expr(d+1),expr(d+1))

def query():
    tbl=random.choice(tables)
    parts=["SELECT"]
    if random.random()<.2: parts.append("DISTINCT")
    n=random.randrange(1,4)
    parts.append(", ".join(expr() for _ in range(n)))
    parts.append("FROM "+tbl)
    if random.random()<.3: parts.append("WHERE "+expr())
    if random.random()<.2: parts.append("GROUP BY "+expr())
    if random.random()<.15: parts.append("HAVING "+expr())
    if random.random()<.3: parts.append("ORDER BY "+", ".join(expr()+(" DESC" if random.random()<.5 else "") for _ in range(random.randrange(1,3))))
    if random.random()<.2: parts.append("LIMIT %d"%random.randrange(0,5))
    if random.random()<.1: parts.append("OFFSET %d"%random.randrange(0,5))
    return " ".join(parts)

bad=0
for i in range(5000):
    q=query()
    try:
        r=minisql.run(q,D)
        if not isinstance(r.columns,list) or not isinstance(r.rows,list): print("SHAPE",q); bad+=1
        for row in r.rows:
            if not isinstance(row,tuple) or len(row)!=len(r.columns):
                print("LEN",q,r.columns,row); bad+=1; break
            for v in row:
                if type(v) not in (type(None),bool,int,float,str):
                    print("TYPE",q,r.columns,row); bad+=1; break
    except minisql.QueryError:
        pass
    except Exception as e:
        print("CRASH",q,type(e).__name__,e); bad+=1
    if bad>10: break
print("bad",bad)

